import java.util.List;

public final class Workflow {
  public record Receipt(String id) {}

  public static final class Audit {
    private final List<String> events;
    public Audit(List<String> events) { this.events = events; }
    public void record(Receipt receipt) { events.add("receipt:" + receipt.id()); }
    public void record(Object value) { events.add("generic:" + String.valueOf(value)); }
  }

  private final Audit audit;
  private final List<String> events;

  public Workflow(Audit audit, List<String> events) {
    this.audit = audit;
    this.events = events;
  }

  public void complete(Receipt receipt) {
    events.add("begin");
    // Completion evidence.
    audit.record(receipt);
    events.add("metric:completion");
    events.add("end");
  }
}

