import java.util.ArrayList;
public final class Driver {
  public static void main(String[] args) {
    var events = new ArrayList<String>();
    var workflow = new Workflow(new Workflow.Audit(events), events);
    workflow.complete(new Workflow.Receipt("r-7"));
    if (events.size() != 4) throw new AssertionError("Wrong count: " + events);
    System.out.println(events);
  }
}

